import { Transform } from "node:stream";
import { parse } from "csv-parse";
import { pipeline } from "node:stream/promises";
import { createReadStream, createWriteStream } from "node:fs";
import { EOL } from "node:os";

// ── Type inference ──────────────────────────────────────────────────

function inferType(value) {
  if (value === "" || value === null || value === undefined) return { value: null, type: "null" };
  // Boolean
  if (value === "true" || value === "TRUE") return { value: true, type: "boolean" };
  if (value === "false" || value === "FALSE") return { value: false, type: "boolean" };
  // Number (int or float)
  if (/^-?\d+$/.test(value)) return { value: parseInt(value, 10), type: "integer" };
  if (/^-?\d+\.\d+$/.test(value)) return { value: parseFloat(value), type: "float" };
  // JSON object/array
  if ((value.startsWith("{") && value.endsWith("}")) || (value.startsWith("[") && value.endsWith("]"))) {
    try {
      const parsed = JSON.parse(value);
      return { value: parsed, type: typeof parsed === "object" ? "json" : typeof parsed };
    } catch {}
  }
  return { value, type: "string" };
}

function inferAndConvert(value) {
  return inferType(value).value;
}

// ── Dot-notation nesting ────────────────────────────────────────────

function setNested(obj, path, value) {
  const keys = path.split(".");
  let current = obj;
  for (let i = 0; i < keys.length - 1; i++) {
    const key = keys[i];
    // Use array index if key is numeric
    const nextKey = keys[i + 1];
    const useArray = /^\d+$/.test(nextKey);
    if (!current[key]) current[key] = useArray ? [] : {};
    current = current[key];
  }
  const lastKey = keys[keys.length - 1];
  if (current[lastKey] !== undefined && Array.isArray(current[lastKey])) {
    current[lastKey].push(value);
  } else if (current[lastKey] !== undefined) {
    current[lastKey] = [current[lastKey], value];
  } else {
    current[lastKey] = value;
  }
}

// ── Field mapping ───────────────────────────────────────────────────

function resolveMapping(header, fieldMap) {
  if (!fieldMap) return header;
  return fieldMap[header] ?? header;
}

// ── Streaming transform ─────────────────────────────────────────────

class CsvToJsonTransform extends Transform {
  constructor({ fieldMap, typeInference = true, nested = true, firstObject = true, onHeader }) {
    super({ objectMode: true });
    this.fieldMap = fieldMap;
    this.typeInference = typeInference;
    this.nested = nested;
    this.firstObject = firstObject;
    this.header = null;
    this.onHeader = onHeader;
    this.headerSent = false;
  }

  _transform(record, _encoding, callback) {
    if (!this.header) {
      this.header = record;
      if (this.onHeader) this.onHeader(this.header);
      return callback();
    }

    let obj = {};
    for (const [i, rawKey] of this.header.entries()) {
      const csvValue = record[i] ?? "";
      const mappedKey = resolveMapping(rawKey, this.fieldMap);
      const value = this.typeInference ? inferAndConvert(csvValue) : csvValue;

      if (this.nested && mappedKey.includes(".")) {
        setNested(obj, mappedKey, value);
      } else {
        obj[mappedKey] = value;
      }
    }

    const prefix = this.firstObject ? "" : ",";
    this.firstObject = false;
    if (!this.headerSent) {
      this.headerSent = true;
      this.push(JSON.stringify(obj));
    } else {
      this.push(",");
      this.push(JSON.stringify(obj));
    }
    callback();
  }
}

// ── Main API ────────────────────────────────────────────────────────

export async function convert({ input, output, fieldMap, typeInference = true, nested = true, delimiter = "," }) {
  return new Promise((resolve, reject) => {
    const headers = [];
    const transform = new CsvToJsonTransform({ fieldMap, typeInference, nested });

    const outStream = output
      ? createWriteStream(output)
      : process.stdout;

    outStream.write("[");

    pipeline(
      createReadStream(input),
      parse({ delimiter, skip_empty_lines: true, relax_column_count: true }),
      transform,
      async function* (source) {
        for await (const chunk of source) {
          yield chunk;
        }
      },
      outStream,
      (err) => {
        if (err) {
          if (output) outStream.close();
          return reject(err);
        }
        // Write closing bracket
        if (output) {
          outStream.write("]" + EOL);
          outStream.end(() => resolve());
        } else {
          process.stdout.write("]" + EOL, () => resolve());
        }
      }
    );
  });
}

// ── In-memory API for small data ────────────────────────────────────

export function convertSync(csvString, { fieldMap, typeInference = true, nested = true, delimiter = "," } = {}) {
  const lines = csvString.trim().split(/\r?\n/);
  if (lines.length < 2) return [];
  const header = parseLine(lines[0], delimiter);
  const result = [];
  for (let i = 1; i < lines.length; i++) {
    const values = parseLine(lines[i], delimiter);
    const obj = {};
    for (let j = 0; j < header.length; j++) {
      const csvValue = values[j] ?? "";
      const mappedKey = resolveMapping(header[j], fieldMap);
      const value = typeInference ? inferAndConvert(csvValue) : csvValue;
      if (nested && mappedKey.includes(".")) {
        setNested(obj, mappedKey, value);
      } else {
        obj[mappedKey] = value;
      }
    }
    result.push(obj);
  }
  return result;
}

// Simple CSV line parser (quoted fields)
function parseLine(line, delimiter) {
  const fields = [];
  let current = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (i + 1 < line.length && line[i + 1] === '"') { current += '"'; i++; }
        else inQuotes = false;
      } else {
        current += ch;
      }
    } else {
      if (ch === '"') { inQuotes = true; }
      else if (ch === delimiter) { fields.push(current); current = ""; }
      else { current += ch; }
    }
  }
  fields.push(current);
  return fields;
}

export { inferType, inferAndConvert, setNested, resolveMapping, CsvToJsonTransform };

#!/usr/bin/env node

import { resolve, parse as parsePath } from "node:path";
import { readFile, writeFile } from "node:fs/promises";
import { convert, convertSync } from "./index.js";

const args = process.argv.slice(2);
function hasFlag(f) { return args.includes(f); }
function getVal(f) { const i = args.indexOf(f); return i !== -1 && args[i + 1] ? args[i + 1] : null; }

const help = `
csv-to-json — Convert CSV files to JSON with type inference & nesting

Usage:
  csv-to-json <input.csv> [output.json] [options]

Options:
  --map <file.json>        Field mapping file (JSON object: { "csv_header": "json_key" })
  --no-type                Disable type inference (everything stays string)
  --no-nest                Disable dot-notation nesting
  -d, --delimiter <char>   CSV delimiter (default: ",")
  -s, --string             Read CSV from stdin or --string value (in-memory mode)
  --help                   Show this help

Examples:
  csv-to-json data.csv
  csv-to-json data.csv output.json --map fields.json
  echo "name,age\\nAlice,30" | csv-to-json -s
  cat data.csv | csv-to-json -s
`;

if (hasFlag("--help") || args.length === 0) { console.log(help); process.exit(0); }

const delimiter = getVal("-d") || getVal("--delimiter") || ",";
const typeInference = !hasFlag("--no-type");
const nested = !hasFlag("--no-nest");
const mapFile = getVal("--map");
const stringMode = hasFlag("-s") || hasFlag("--string");

let fieldMap = null;
if (mapFile) {
  fieldMap = JSON.parse(await readFile(resolve(mapFile), "utf8"));
}

if (stringMode) {
  const csvStr = getVal("-s") || getVal("--string");
  let data;
  if (csvStr) {
    data = convertSync(csvStr, { fieldMap, typeInference, nested, delimiter });
  } else {
    // Read from stdin
    const chunks = [];
    for await (const chunk of process.stdin) chunks.push(chunk);
    data = convertSync(Buffer.concat(chunks).toString(), { fieldMap, typeInference, nested, delimiter });
  }
  console.log(JSON.stringify(data, null, 2));
} else {
  // Positional args: input [output]
  const positional = args.filter(a => !a.startsWith("-"));
  const inputFile = positional[0];
  const outputFile = positional[1] || null;

  await convert({ input: resolve(inputFile), output: outputFile ? resolve(outputFile) : null, fieldMap, typeInference, nested, delimiter });
}

import { strict as assert } from "node:assert";
import { convertSync, inferType, setNested } from "./index.js";

// ── Type inference ──────────────────────────────────────────────────

assert.deepEqual(inferType("42"), { value: 42, type: "integer" });
assert.deepEqual(inferType("3.14"), { value: 3.14, type: "float" });
assert.deepEqual(inferType("true"), { value: true, type: "boolean" });
assert.deepEqual(inferType("false"), { value: false, type: "boolean" });
assert.deepEqual(inferType(""), { value: null, type: "null" });
assert.deepEqual(inferType("hello"), { value: "hello", type: "string" });
assert.deepEqual(inferType('{"a":1}'), { value: { a: 1 }, type: "json" });
assert.deepEqual(inferType("[1,2]"), { value: [1, 2], type: "json" });
assert.deepEqual(inferType("-7"), { value: -7, type: "integer" });
assert.deepEqual(inferType("-2.5"), { value: -2.5, type: "float" });
assert.deepEqual(inferType("not a number"), { value: "not a number", type: "string" });

// ── Nested object ───────────────────────────────────────────────────

const obj = {};
setNested(obj, "address.city", "NYC");
setNested(obj, "address.zip", "10001");
assert.deepEqual(obj.address, { city: "NYC", zip: "10001" });

const obj2 = {};
setNested(obj2, "tags.0", "js");
setNested(obj2, "tags.1", "ts");
assert.deepEqual(obj2.tags, ["js", "ts"]);

// ── Basic CSV conversion ────────────────────────────────────────────

const csv1 = `name,age,active
Alice,30,true
Bob,25,false`;

const result1 = convertSync(csv1);
assert.equal(result1.length, 2);
assert.equal(result1[0].name, "Alice");
assert.equal(result1[0].age, 30);
assert.equal(result1[0].active, true);
assert.equal(result1[1].age, 25);
assert.equal(result1[1].active, false);

// ── With field mapping ──────────────────────────────────────────────

const result2 = convertSync(csv1, { fieldMap: { name: "full_name", age: "years" } });
assert.equal(result2[0].full_name, "Alice");
assert.equal(result2[0].years, 30);
assert.equal(result2[0].full_name, undefined || "Alice"); // mapped
assert.ok(!("name" in result2[0]));

// ── Nested fields ───────────────────────────────────────────────────

const csv3 = `user.name,user.address.city,user.address.zip
Alice,NYC,10001`;

const result3 = convertSync(csv3);
assert.deepEqual(result3[0].user, { name: "Alice", address: { city: "NYC", zip: "10001" } });

// ── No type inference ───────────────────────────────────────────────

const result4 = convertSync(csv1, { typeInference: false });
assert.equal(typeof result4[0].age, "string");
assert.equal(result4[0].age, "30");

// ── No nesting ──────────────────────────────────────────────────────

const result5 = convertSync(csv3, { nested: false });
assert.equal(result5[0]["user.address.city"], "NYC");
assert.ok(!result5[0].user);

// ── Custom delimiter ────────────────────────────────────────────────

const csv6 = `name;age;score
Eve;28;95.5`;
const result6 = convertSync(csv6, { delimiter: ";" });
assert.equal(result6[0].name, "Eve");
assert.equal(result6[0].age, 28);
assert.equal(result6[0].score, 95.5);

// ── Quoted fields ───────────────────────────────────────────────────

const csv7 = `name,description
Alice,"Hello, world"
Bob,"Line1\nLine2"`;
const result7 = convertSync(csv7);
assert.equal(result7[0].description, "Hello, world");
assert.equal(result7[1].description, "Line1\nLine2");

// ── Empty CSV ───────────────────────────────────────────────────────

assert.deepEqual(convertSync(""), []);

// ── Header only ─────────────────────────────────────────────────────

assert.deepEqual(convertSync("a,b,c"), []);

console.log("✅ All tests passed");

import { Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import { createReadStream, createWriteStream } from "node:fs";
import { EOL } from "node:os";

// ── Type inference ──────────────────────────────────────────────────

function inferType(value) {
  if (value === "" || value === null || value === undefined) return { value: null, type: "null" };
  if (value === "true" || value === "TRUE") return { value: true, type: "boolean" };
  if (value === "false" || value === "FALSE") return { value: false, type: "boolean" };
  if (/^-?\d+$/.test(value)) return { value: parseInt(value, 10), type: "integer" };
  if (/^-?\d+\.\d+$/.test(value)) return { value: parseFloat(value), type: "float" };
  if ((value.startsWith("{") && value.endsWith("}")) || (value.startsWith("[") && value.endsWith("]"))) {
    try {
      const parsed = JSON.parse(value);
      return { value: parsed, type: typeof parsed === "object" ? "json" : typeof parsed };
    } catch {}
  }
  return { value, type: "string" };
}

function inferAndConvert(value) {
  return inferType(value).value;
}

// ── Dot-notation nesting ────────────────────────────────────────────

function setNested(obj, path, value) {
  const keys = path.split(".");
  let current = obj;
  for (let i = 0; i < keys.length - 1; i++) {
    const key = keys[i];
    if (!current[key]) {
      const nextKey = keys[i + 1];
      current[key] = /^\d+$/.test(nextKey) ? [] : {};
    }
    current = current[key];
  }
  const lastKey = keys[keys.length - 1];
  current[lastKey] = value;
}

// ── Field mapping ───────────────────────────────────────────────────

function resolveMapping(header, fieldMap) {
  if (!fieldMap) return header;
  return fieldMap[header] ?? header;
}

// ── CSV line parser ─────────────────────────────────────────────────

function parseLine(line, delimiter) {
  const fields = [];
  let current = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (i + 1 < line.length && line[i + 1] === '"') { current += '"'; i++; }
        else inQuotes = false;
      } else {
        current += ch;
      }
    } else {
      if (ch === '"') { inQuotes = true; }
      else if (ch === delimiter) { fields.push(current); current = ""; }
      else { current += ch; }
    }
  }
  fields.push(current);
  return fields;
}

// ── Streaming CSV parser transform ──────────────────────────────────

class CsvParseStream extends Transform {
  constructor(delimiter = ",") {
    super({ decodeStrings: false });
    this.delimiter = delimiter;
    this.buffer = "";
  }

  _transform(chunk, _encoding, callback) {
    this.buffer += chunk;
    let idx;
    while ((idx = this.findLineEnd()) !== -1) {
      const line = this.buffer.slice(0, idx);
      this.buffer = this.buffer.slice(idx + 1);
      if (line.trim()) {
        this.push(parseLine(line, this.delimiter));
      }
    }
    callback();
  }

  _flush(callback) {
    if (this.buffer.trim()) {
      this.push(parseLine(this.buffer.trim(), this.delimiter));
    }
    callback();
  }

  findLineEnd() {
    let inQuotes = false;
    for (let i = 0; i < this.buffer.length; i++) {
      const ch = this.buffer[i];
      if (ch === '"') inQuotes = !inQuotes;
      else if (!inQuotes && ch === "\n") return i;
      else if (!inQuotes && ch === "\r" && this.buffer[i + 1] === "\n") return i;
    }
    return -1;
  }
}

// ── Streaming CSV→JSON transform ────────────────────────────────────

class CsvToJsonTransform extends Transform {
  constructor({ fieldMap, typeInference = true, nested = true, onHeader }) {
    super({ objectMode: true });
    this.fieldMap = fieldMap;
    this.typeInference = typeInference;
    this.nested = nested;
    this.header = null;
    this.onHeader = onHeader;
    this.firstRow = true;
  }

  _transform(fields, _encoding, callback) {
    if (!this.header) {
      this.header = fields;
      if (this.onHeader) this.onHeader(this.header);
      return callback();
    }

    let obj = {};
    for (let i = 0; i < this.header.length; i++) {
      const rawKey = this.header[i];
      const csvValue = fields[i] ?? "";
      const mappedKey = resolveMapping(rawKey, this.fieldMap);
      const value = this.typeInference ? inferAndConvert(csvValue) : csvValue;

      if (this.nested && mappedKey.includes(".")) {
        setNested(obj, mappedKey, value);
      } else {
        obj[mappedKey] = value;
      }
    }

    const prefix = this.firstRow ? "" : ",";
    this.firstRow = false;
    this.push(prefix + JSON.stringify(obj));
    callback();
  }
}

// ── Streaming convert API ───────────────────────────────────────────

export async function convert({ input, output, fieldMap, typeInference = true, nested = true, delimiter = "," }) {
  return new Promise((resolve, reject) => {
    const outStream = output ? createWriteStream(output) : process.stdout;

    const parser = new CsvParseStream(delimiter);
    const transformer = new CsvToJsonTransform({ fieldMap, typeInference, nested });

    outStream.write("[");

    pipeline(
      createReadStream(input),
      parser,
      transformer,
      // Need a passthrough since pipeline expects streams
      new Transform({
        objectMode: true,
        transform(chunk, _enc, cb) { cb(null, chunk); },
      }),
      new Transform({
        objectMode: true,
        construct(ready) {
          this.on("data", (d) => outStream.write(d));
          this.on("end", () => {
            outStream.write("]" + EOL);
            outStream.end(() => resolve());
          });
          ready();
        },
      }),
      (err) => {
        if (err) {
          outStream.end();
          reject(err);
        }
      }
    );
  });
}

// ── In-memory convert API ───────────────────────────────────────────

export function convertSync(csvString, { fieldMap, typeInference = true, nested = true, delimiter = "," } = {}) {
  const lines = csvString.trim().split(/\r?\n/);
  if (lines.length < 2) return [];
  const header = parseLine(lines[0], delimiter);
  const result = [];
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const values = parseLine(line, delimiter);
    const obj = {};
    for (let j = 0; j < header.length; j++) {
      const csvValue = values[j] ?? "";
      const mappedKey = resolveMapping(header[j], fieldMap);
      const value = typeInference ? inferAndConvert(csvValue) : csvValue;
      if (nested && mappedKey.includes(".")) {
        setNested(obj, mappedKey, value);
      } else {
        obj[mappedKey] = value;
      }
    }
    result.push(obj);
  }
  return result;
}

export { inferType, inferAndConvert, setNested, resolveMapping, parseLine, CsvParseStream, CsvToJsonTransform };

