#!/usr/bin/env node

import { resolve } from "node:path";
import { readFile } from "node:fs/promises";
import { convert, convertSync } from "./index.js";

function parseArgs(argv) {
  const positional = [];
  const flags = new Set();
  const vals = {};
  let i = 0;
  while (i < argv.length) {
    if (argv[i].startsWith("-")) {
      const nextIsVal = i + 1 < argv.length && !argv[i + 1].startsWith("-");
      if (nextIsVal) { vals[argv[i]] = argv[i + 1]; i += 2; }
      else { flags.add(argv[i]); i++; }
    } else { positional.push(argv[i]); i++; }
  }
  return {
    positional,
    has(f) { return flags.has(f) || f in vals; },
    val(f) { return vals[f] ?? null; },
  };
}

const help = `
csv-to-json — Convert CSV files to JSON with type inference & nesting

Usage:
  csv-to-json <input.csv> [output.json] [options]

Options:
  --map <file.json>        Field mapping file (JSON: { "csv_header": "json_key" })
  --no-type                Disable type inference (keep everything as strings)
  --no-nest                Disable dot-notation nesting
  -d, --delimiter <char>   CSV delimiter (default: ",")
  -s                       Read from stdin (in-memory mode)
  --string <csv>           Parse an inline CSV string
  --help                   Show this help

Examples:
  csv-to-json data.csv
  csv-to-json data.csv output.json --map fields.json
  echo "name,age" | csv-to-json -s
  csv-to-json --string "a,b\n1,2"
`;

const parsed = parseArgs(process.argv.slice(2));

const stringMode = parsed.has("-s") || parsed.has("--string");
if (parsed.has("--help") || (parsed.positional.length === 0 && !stringMode)) {
  console.log(help);
  process.exit(0);
}

const delimiter = parsed.val("-d") || parsed.val("--delimiter") || ",";
const typeInference = !parsed.has("--no-type");
const nested = !parsed.has("--no-nest");
const mapFile = parsed.val("--map");

let fieldMap = null;
if (mapFile) fieldMap = JSON.parse(await readFile(resolve(mapFile), "utf8"));

if (stringMode) {
  const csvStr = parsed.val("--string");
  let data;
  if (csvStr) {
    data = convertSync(csvStr, { fieldMap, typeInference, nested, delimiter });
  } else {
    const chunks = [];
    for await (const chunk of process.stdin) chunks.push(chunk);
    data = convertSync(Buffer.concat(chunks).toString(), { fieldMap, typeInference, nested, delimiter });
  }
  console.log(JSON.stringify(data, null, 2));
} else {
  const inputFile = parsed.positional[0];
  const outputFile = parsed.positional[1] || null;
  await convert({ input: resolve(inputFile), output: outputFile ? resolve(outputFile) : null, fieldMap, typeInference, nested, delimiter });
}

